def best_loss(path):
    """返回日志中最低的 loss"""
    losses = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            if "loss=" in line:
                losses.append(float(line.split("loss=")[1].split()[0]))
    if not losses:
        return None
    return round(min(losses), 2)
